// Shape of src/plan.json. Generated by scripts/parse-plan.ts from the two markdown files.

export type RestCat = 'jump' | 'strength' | 'contrast' | 'trick' | 'flex';
export type TestKey = 'jump' | 'kick' | '540' | '720';

interface ExBase {
  name: string;
  /** Prescription as shown in the plan, already adjusted for deload weeks. */
  do: string;
  cat: RestCat;
  restSec: number;
  note?: string;
}

export interface SetsEx extends ExBase {
  kind: 'sets';
  sets: number;
  reps: number;
  perSide: boolean;
  /** Big text override, e.g. "20 m" for sprints. */
  target?: string;
  unit: string;
  /** "Set" by default, "Rep" for prescriptions like "6 reps". */
  setWord: string;
  /** Superset parts done back to back each set, e.g. pike lift then straddle lift. */
  parts?: string[];
  /** Hold after the last set, e.g. pancake "then 60 s hold". */
  finalHoldSec?: number;
}

export interface HoldEx extends ExBase {
  kind: 'hold';
  sets: number;
  sec: number;
  perSide: boolean;
}

export interface PnfPhase {
  label: string;
  sec: number;
}

export interface PnfEx extends ExBase {
  kind: 'pnf';
  rounds: number;
  perSide: boolean;
  phases: PnfPhase[];
}

export interface ContrastEx extends ExBase {
  kind: 'contrast';
  rounds: number;
  pushSec: number;
  jumps: number;
}

export interface CircuitItem {
  /** Short name from the prescription, e.g. "leg raises". */
  name: string;
  /** Full description from the Rules section, e.g. "Lying straight-leg raise above 90° (2 s hold)". */
  desc?: string;
  reps?: number;
  sec?: number;
  perSide: boolean;
  note?: string;
}

export interface CircuitEx extends ExBase {
  kind: 'circuit';
  sets: number;
  items: CircuitItem[];
}

export interface RoundsEx extends ExBase {
  kind: 'rounds';
  rounds: number;
  /** Shuffled per round when the session starts. */
  options: string[];
}

export interface EmomEx extends ExBase {
  kind: 'emom';
  minutes: number;
  perMinute: string;
  /** One cue per minute, cycled. */
  cues: string[];
}

export interface TimedEx extends ExBase {
  kind: 'timed';
  sec: number;
}

export interface TestEx extends ExBase {
  kind: 'test';
  test: TestKey;
  attempts: number;
  perSide: boolean;
  log: 'best' | 'landed' | 'rotations';
}

export type Exercise = SetsEx | HoldEx | PnfEx | ContrastEx | CircuitEx | RoundsEx | EmomEx | TimedEx | TestEx;

export interface WarmupItem {
  name: string;
  sec?: number;
  sets?: number;
  reps?: number;
  unit?: string;
  perSide: boolean;
}

export interface Warmup {
  name: string;
  items: WarmupItem[];
}

export interface Day {
  day: number;
  title: string;
  warmup: Warmup | null;
  exercises: Exercise[];
  notes: string[];
}

export interface Week {
  week: number;
  deload: boolean;
  days: Day[];
}

export interface Month {
  month: number;
  target: string;
  /** The first sentence of the target, split into separate goals. */
  goals: string[];
  /** The rest of the target, e.g. "Expect the ball to go up most weeks." */
  targetNote: string;
  weeks: Week[];
}

export interface GtgPart {
  name: string;
  /** Hold seconds; otherwise a rep step. */
  sec?: number;
  reps?: number;
  perSide: boolean;
  note?: string;
}

export interface GtgVersion {
  months: number[];
  text: string;
  parts: GtgPart[];
}

export interface GtgSet {
  letter: string;
  label: string;
  versions: GtgVersion[];
}

export interface GtgColumn {
  days: number[];
  letters: string[];
}

export interface Gtg {
  rules: string[];
  deloadSlots: number;
  sets: GtgSet[];
  times: string[];
  columns: GtgColumn[];
}

export interface Plan {
  rules: { label: string; text: string }[];
  rest: Record<RestCat, number>;
  months: Month[];
  gtg: Gtg;
}
